#!/usr/bin/env python3
"""Copy the catalog generated by the matching agent release into Defense."""
import argparse
import json
from pathlib import Path
import shutil

root = Path(__file__).resolve().parents[1]
parser = argparse.ArgumentParser(description=__doc__)
parser.add_argument('--agent-root', type=Path, default=root.parent / 'xdr-agent')
args = parser.parse_args()
source = args.agent_root / 'internal/detection/malware/bundle/catalog.json'
catalog = json.loads(source.read_text())
if catalog['platform'] != 'linux' or not catalog['rules'] or catalog['rule_count'] != len(catalog['rules']):
    raise SystemExit('Agent release catalog is invalid')
target = root / 'server/data/yara-core-linux.json'
target.parent.mkdir(parents=True, exist_ok=True)
shutil.copyfile(source, target)
print(f"Packaged {catalog['rule_count']} Linux rules; SHA-256 {catalog['rules_sha256']}")
